import React from 'react'
import { connect } from 'react-redux'
import QueryString from 'query-string'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import {
  Row,
  notification,
  Input,
  Button,
  Icon,
  DatePicker,
  Select
} from 'antd'
import ReconActions from '../../redux/recon/actions'
import PolicyActions from '../../../redux/policy/actions'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'

import TableWrapper, { TableStyleWrapper } from './table.style'

const Option = Select.Option

const { getReconList, resetReduxStateRecon } = ReconActions
const { getPartners, getProducts } = PolicyActions

class TableComponent extends React.Component {
  state = {
    searchTextQuery: {},
    isChange: false,
    isClear: false,
    showCreateRecon: false,
    searchParams: {}
  }

  componentDidMount () {
    this.props.getPartners()
    this.props.getProducts()
    const querySearch = QueryString.parse(this.props.location.search)
    this.setState({ searchParams: querySearch })
    if (Object.keys(querySearch).length > 0) {
      this.fetch({ query: querySearch })
    } else {
      this.fetch()
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      getAutoReconListLoading,
      getAutoReconListError,
      getAutoReconListMessage
    } = nextProps
    if (!getAutoReconListLoading && !!getAutoReconListError && !!getAutoReconListMessage) {
      notification.error({
        title: 'Error',
        message: getAutoReconListMessage
      })

      this.props.resetReduxStateRecon(['getAutoReconListMessage'])
    }
  }

  fetch = (payload = { query: { limit: 50, page: 1 } }) => {
    const { location, history } = this.props
    const { querySearch } = this.state
    const { query = {} } = payload
    const { page = 1, limit = 50 } = query
    const queryPage = Number(page)
    const queryLimit = Number(limit)
    const finalQuery = {
      page: queryPage,
      limit: queryLimit,
      ...payload.query
    }
    // finalQuery
    const queryString = QuerySearchBuilder(finalQuery)
    history.push({
      pathname: location.pathname,
      search: queryString
    })
    this.setState({
      page: queryPage,
      limit: queryLimit,
      querySearch: { ...querySearch, ...finalQuery }
    }, () => this.props.getReconList({ query: finalQuery }))
  }

  onSearch = (e) => {
    e.preventDefault()
    const { searchTextQuery } = this.state
    const { location, history } = this.props
    const finalFilter = { ...searchTextQuery }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({
      pathname: location.pathname,
      search: searchQuery
    })
    if (Object.values(searchTextQuery).length > 0) {
      this.setState({
        filterPartner: false,
        searchTextQuery: finalFilter
      })
      this.props.filter(finalFilter)
    }
  }

  onInputChange = (event, identifier) => {
    this.setState({
      searchTextQuery: { [identifier]: event.target.value },
      isChange: true
    })
  }

  detail = (id) => {
    const { history, location } = this.props
    history.push(`${location.pathname}/${id}`)
  }

  showCreateRecon = () => {
    this.setState(prevState => ({
      showCreateRecon: !prevState.showCreateRecon
    }))
  }

  handleTableChange = (pagination) => {
    const { querySearch } = this.state
    const { pageSize, current } = pagination
    const finalFilter = {
      ...querySearch,
      page: current,
      limit: pageSize
    }
    this.fetch({ query: finalFilter })
  }

  handleClearFilter = () => {
    this.setState({ querySearch: {} })
    this.fetch()
  }

  handleSearch = (selectedKeys, dataIndex) => {
    const { location, history } = this.props
    const { querySearch } = this.state
    const params = new URLSearchParams(location)
    delete params.limit
    delete params.offset
    params[dataIndex] = selectedKeys
    params.page = 1
    params.limit = 50
    this.setState({ querySearch: { ...querySearch, [dataIndex]: selectedKeys[0] } })
    const search = QuerySearchBuilder(params)
    history.push({ pathname: location.pathname, search })
    this.props.getReconList({ query: params })
  }

  renderSearch = (type, dataIndex, setSelectedKeys, selectedKeys) => {
    const { products, productsLoading } = this.props
    const selectStyle = {
      width: 200,
      display: 'block',
      marginBottom: 5
    }
    if (type === 'date') {
      return (
        <DatePicker
          format='YYYY-MM-DD'
          placeholder={`Search ${dataIndex}`}
          onPressEnter={() => this.handleSearch(selectedKeys, dataIndex)}
          onChange={(date, dateString) => setSelectedKeys(dateString ? [dateString] : [])}
        />
      )
    } if (type === 'select-product') {
      return (
        <Select
          placeholder='Product'
          showSearch
          dropdownMatchSelectWidth={false}
          style={selectStyle}
          onSelect={this.onSelectProduct}
          onPressEnter={() => this.handleSearch(selectedKeys, dataIndex)}
          onChange={(values) => setSelectedKeys(values)}
          filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          loading={!!productsLoading}
          disabled={!!productsLoading}
        >
          {products.map(({ id, display_name: displayName }) => (<Option value={id} key={displayName}>{displayName}</Option>))}
        </Select>
      )
    } else {
      return (
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
      )
    }
  }

  getColumnSearchProps = (dataIndex, type) => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys }) => (
      <div style={{ padding: 8 }}>
        {this.renderSearch(type, dataIndex, setSelectedKeys, selectedKeys)}
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    }
  })

  render () {
    const {
      reconData,
      reconMetadata,
      getAutoReconListLoading
    } = this.props
    const {
      page,
      limit
    } = this.state
    const columns = [{
      title: 'Action',
      dataIndex: 'name',
      key: 'action',
      render: (_, record) => {
        return (<span className='anchor' onClick={() => this.detail(record.id)}>View</span>)
      }
    }, {
      dataIndex: 'name',
      key: 'name',
      title: 'Recon Name',
      ...this.getColumnSearchProps('name', 'string')
    }, {
      title: 'Partner',
      dataIndex: 'partner',
      key: 'partner',
      ...this.getColumnSearchProps('partner', 'string')
    }, {
      title: 'Product',
      key: 'product',
      render: ({ display_name: displayName, product }) => displayName || product,
      ...this.getColumnSearchProps('product', 'select-product')
    }, {
      title: 'Package',
      dataIndex: 'package',
      key: 'package',
      ...this.getColumnSearchProps('package', 'string')
    }, {
      title: 'Created At',
      dataIndex: 'created_at',
      render: date => moment(date).tz('Asia/Jakarta').format('lll'),
      key: 'created_at'
    }, {
      title: 'From Date',
      dataIndex: 'from_date',
      key: 'from_date',
      ...this.getColumnSearchProps('from_date', 'date')
    }, {
      title: 'To Date',
      dataIndex: 'to_date',
      key: 'to_date',
      ...this.getColumnSearchProps('to_date', 'date')
    }, {
      title: 'Status',
      dataIndex: 'status',
      key: 'status'
    }, {
      title: 'Remarks',
      dataIndex: 'remarks',
      key: 'remarks'
    }, {
      title: 'Source',
      dataIndex: 'source',
      key: 'source'
    }, {
      title: 'Created by',
      dataIndex: 'uploaded_by',
      key: 'uploaded_by'
    }]

    return (
      <TableStyleWrapper>
        <Row type='flex' justify='space-between' className='header-row'>
          <div className='header'>Recon List</div>
          <Button
            icon='delete'
            onClick={this.handleClearFilter}
          >
            Clear Filter
          </Button>
        </Row>
        <Row>
          <TableWrapper
            columns={columns}
            bordered
            loading={!!getAutoReconListLoading}
            dataSource={reconData}
            rowKey={record => record.id}
            onChange={this.handleTableChange}
            pagination={{
              pageSize: limit,
              total: reconMetadata.total,
              current: page
            }}
          />
        </Row>
      </TableStyleWrapper>
    )
  }
}

TableComponent.propTypes = {
  reconData: PropTypes.array.isRequired,
  reconMetadata: PropTypes.object.isRequired,
  partners: PropTypes.array.isRequired
}

TableComponent.defaultProps = {
  reconData: [],
  reconMetadata: {},
  partners: []
}

export default connect(
  state => ({
    reconData: state.Recon.data,
    reconMetadata: state.Recon.reconMetadata,

    products: state.Policy.products,
    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,
    partners: state.Policy.partners,

    gerAutoReconListMessage: state.Recon.gerAutoReconListMessage,
    getAutoReconListLoading: state.Loading.GET_AUTO_RECON_LIST,
    getAutoReconListError: state.Error.GET_AUTO_RECON_LIST
  }),
  {
    getProducts,
    getPartners,
    getReconList,
    resetReduxStateRecon
  }
)(TableComponent)
